#!/usr/bin/env python3
import json
import re
from docx import Document

# Read employee data
with open('/root/employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template
doc = Document('/root/offer_letter_template.docx')

def replace_placeholders_in_paragraph(paragraph, replacements):
    """Replace placeholders in a paragraph while preserving formatting"""
    for key, value in replacements.items():
        placeholder = f"{{{{{key}}}}}"
        if placeholder in paragraph.text:
            # Replace inline
            for run in paragraph.runs:
                if placeholder in run.text:
                    run.text = run.text.replace(placeholder, str(value))

def replace_placeholders_in_table(table, replacements):
    """Replace placeholders in table cells"""
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                replace_placeholders_in_paragraph(paragraph, replacements)

def process_conditional_sections(doc, data):
    """Process conditional sections based on RELOCATION_PACKAGE"""
    keep_relocation = data.get('RELOCATION_PACKAGE', '').lower() == 'yes'

    paragraphs_to_remove = []
    inside_conditional = False
    conditional_paragraphs = []

    for i, paragraph in enumerate(doc.paragraphs):
        text = paragraph.text.strip()

        if '{{IF_RELOCATION}}' in text:
            inside_conditional = True
            paragraphs_to_remove.append(i)
            continue

        if '{{END_IF_RELOCATION}}' in text:
            inside_conditional = False
            paragraphs_to_remove.append(i)
            continue

        if inside_conditional:
            if not keep_relocation:
                paragraphs_to_remove.append(i)

    # Remove paragraphs in reverse order to maintain indices
    for idx in reversed(paragraphs_to_remove):
        p = doc.paragraphs[idx]
        p._element.getparent().remove(p._element)

# Prepare replacements dictionary
replacements = {key: value for key, value in data.items()}

# Process conditional sections first
process_conditional_sections(doc, data)

# Replace placeholders in paragraphs
for paragraph in doc.paragraphs:
    replace_placeholders_in_paragraph(paragraph, replacements)

# Replace placeholders in tables
for table in doc.tables:
    replace_placeholders_in_table(table, replacements)

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print("Offer letter successfully created at /root/offer_letter_filled.docx")

